--
-- Table structure for table `mes_pro_process_pool_event`
--

DROP TABLE IF EXISTS `mes_pro_process_pool_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_process_pool_event` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工序池提交事件ID',
  `pool_id` bigint NOT NULL COMMENT '工序池ID',
  `event_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交事件类型',
  `work_order_id` bigint NOT NULL COMMENT '生产工单ID',
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `route_process_id` bigint NOT NULL COMMENT '路线工序ID',
  `process_id` bigint NOT NULL COMMENT '工序ID',
  `actual_employee_id` bigint NOT NULL COMMENT '实际员工ID',
  `device_account_id` bigint DEFAULT NULL COMMENT '设备账号ID；PQC_TASK 来源事件可为空',
  `device_id` bigint DEFAULT NULL COMMENT '设备ID；PQC_TASK 来源事件可为空',
  `workstation_id` bigint DEFAULT NULL COMMENT '工位ID；PQC_TASK 来源事件可为空',
  `template_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板类型',
  `feedback_source_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报工来源类型',
  `feedback_source_id` bigint NOT NULL COMMENT '报工来源ID',
  `recordbook_source_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录本来源类型',
  `recordbook_source_id` bigint NOT NULL COMMENT '记录本来源ID',
  `raw_payload` json NOT NULL COMMENT '原始 payload',
  `pqc_task_id` bigint GENERATED ALWAYS AS ((case when regexp_like(json_unquote(json_extract(`raw_payload`,_utf8mb4'$.pqcTaskId')),_utf8mb4'^[0-9]+$') then cast(json_unquote(json_extract(`raw_payload`,_utf8mb4'$.pqcTaskId')) as unsigned) else NULL end)) STORED COMMENT 'PQC task id extracted from raw_payload for AC-D32 timeline joins',
  `server_submit_time` datetime NOT NULL COMMENT '服务端提交时间',
  `signature_id` bigint NOT NULL COMMENT '电子签名ID',
  `signature_user_id` bigint NOT NULL COMMENT '电子签名用户ID',
  `signature_snapshot` json DEFAULT NULL COMMENT '电子签名快照',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_mes_pro_process_pool_event_signature` (`tenant_id`,`signature_id`,`deleted`),
  KEY `idx_mes_pro_process_pool_event_pool` (`tenant_id`,`pool_id`),
  KEY `idx_mes_pro_process_pool_event_context` (`tenant_id`,`work_order_id`,`route_id`,`route_process_id`,`process_id`),
  KEY `idx_mes_pro_process_pool_event_time` (`tenant_id`,`server_submit_time`),
  KEY `idx_mes_pp_event_timeline_acd32` (`tenant_id`,`deleted`,`template_type`,`actual_employee_id`,`process_id`,`work_order_id`,`server_submit_time`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 工序池提交事件';
/*!40101 SET character_set_client = @saved_cs_client */;

