DROP TABLE IF EXISTS `mes_pro_process_pool_quantity_fragment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_process_pool_quantity_fragment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '数量片段ID',
  `pool_id` bigint NOT NULL COMMENT '工序池ID',
  `event_id` bigint NOT NULL COMMENT '工序池提交事件ID',
  `work_order_id` bigint NOT NULL COMMENT '生产工单ID',
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `route_process_id` bigint NOT NULL COMMENT '路线工序ID',
  `process_id` bigint NOT NULL COMMENT '工序ID',
  `source_quantity_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源数量类型',
  `quality_status` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '质量状态',
  `total_quantity` decimal(24,6) NOT NULL COMMENT '总数量',
  `allocated_quantity` decimal(24,6) NOT NULL DEFAULT '0.000000' COMMENT '已分配数量',
  `available_quantity` decimal(24,6) NOT NULL DEFAULT '0.000000' COMMENT '可用数量',
  `allocation_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVAILABLE' COMMENT '分配状态',
  `locked` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否锁定',
  `raw_payload` json DEFAULT NULL COMMENT '数量片段原始 payload',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_mes_pro_process_pool_fragment_event` (`tenant_id`,`event_id`),
  KEY `idx_mes_pro_process_pool_fragment_pool` (`tenant_id`,`pool_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 工序池数量片段';
